import {spawnSync} from 'node:child_process';
import {writeFileSync,readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
const src="/run/media/zenobius/Store/Projects/Mine/Github/Dotfiles.worktrees/feature-skill-contract-manifests-16-web-design-metadata", scope="mise/conf.d/devtools-agent/bundles/creator/skills/web-design", ev="/run/media/zenobius/Store/Projects/Mine/Github/Dotfiles/workflows/skill-contract-manifests-16-web-design-metadata/artifacts/evidence/fix-0056";
const save=(name,value)=>writeFileSync(ev+'/'+name,typeof value==='string'?value:JSON.stringify(value,null,2)+'
',{flag:'wx'});
const runtime=['scripts/sources.ts','scripts/source-metadata.ts','tests/source-metadata-smoke.ts'].map(p=>({path:scope+'/'+p,sha256:createHash('sha256').update(readFileSync(src+'/'+scope+'/'+p)).digest('hex')}));save('tested-bindings.json',runtime);
for(const [name,argv] of [['help',[src+'/'+scope+'/scripts/sources.ts','--help']],['native',[src+'/'+scope+'/tests/source-metadata-smoke.ts']]]){
 const start=new Date().toISOString(), t=performance.now();const r=spawnSync(argv[0],argv.slice(1),{cwd:'/tmp',encoding:'utf8',maxBuffer:16*1024*1024});const duration=(performance.now()-t)/1000;
 const record={argv,cwd:'/tmp',started_at:start,finished_at:new Date().toISOString(),duration_seconds:duration,exit_code:r.status,signal:r.signal,stdout:r.stdout,stderr:r.stderr,error:r.error?.message};save(name+'-smoke.json',record);save(name+'-stdout.txt',r.stdout);save(name+'-stderr.txt',r.stderr);
 if(r.status!==0||r.stderr!=='')throw Error(name+' execution failed; stop');
 if(name==='help'){if(!r.stdout.includes('not the current working directory.'))throw Error('Expanded help missing');save('help-validation.json',{expanded_term:true,exit_code:0,commands_and_authority:r.stdout});}
 else {const lines=r.stdout.trimEnd().split('
');const rows=lines.filter(l=>l.startsWith('{')).map(l=>JSON.parse(l));const summary=lines.filter(l=>!l.startsWith('{'));save('native-row-observation.json',{rows,summary}); console.log(JSON.stringify({name,rows:rows.length,summary,first:rows[0],duration_seconds:duration}));}
 console.log(name+' exit '+r.status+' stderr '+JSON.stringify(r.stderr));
}
